export interface CoreProjectSettingsUpdateInputMarketingAnalyticsConfig {
    /** Column mapping per external data source, keyed by source id. Tells marketing analytics which column holds campaign, source, cost, clicks and impressions for that source. */
    sources_map?: CoreProjectSettingsUpdateRequestSchema34
    /** Conversion goals to attribute against, in display order. Each goal points at an event, an action or a data warehouse table, and carries a schema_map describing which fields hold the UTM parameters, the timestamp and the distinct id. Replaces the whole list on write. */
    conversion_goals?: CoreProjectSettingsUpdateRequestSchema37
    /** How many days back a touchpoint can be credited for a conversion. Between 1 and 90. */
    attribution_window_days?: CoreProjectSettingsUpdateRequestSchema129
    /** How credit is split across touchpoints when a person saw several campaigns before converting.
     *
     * * `first_touch` - First Touch
     * * `last_touch` - Last Touch
     * * `linear` - Linear
     * * `time_decay` - Time Decay
     * * `position_based` - Position Based */
    attribution_mode?: CoreProjectSettingsUpdateRequestSchema130
    /** Whether marketing analytics drops traffic matching the project's test-account filters. Off by default. */
    filter_test_accounts?: CoreProjectSettingsUpdateRequestSchema131
    /** Manual campaign name aliases, keyed by integration type then by canonical campaign name, with the list of names that should be folded into it. Applied before automatic matching. */
    campaign_name_mappings?: CoreProjectSettingsUpdateRequestSchema132
    /** Custom UTM source values to fold into an integration, keyed by integration type. A UTM source can only belong to one integration. */
    custom_source_mappings?: CoreProjectSettingsUpdateRequestSchema135
    /** Which field to match campaigns on per integration type, campaign_name or campaign_id. Manual mappings in campaign_name_mappings still take precedence. */
    campaign_field_preferences?: CoreProjectSettingsUpdateRequestSchema138
}

export interface CoreProjectSettingsUpdateInputCustomerAnalyticsConfig {
    /** Event used as the activity signal (DAU/WAU/MAU). */
    activity_event?: JsonValue | null
    /** Event used to count signup pageviews on dashboards. */
    signup_pageview_event?: JsonValue | null
    /** Event used to count signups on dashboards. */
    signup_event?: JsonValue | null
    /** Event used to count subscriptions on dashboards. */
    subscription_event?: JsonValue | null
    /** Event used to count payments on dashboards. */
    payment_event?: JsonValue | null
    /** Index of the group type to treat as an Account in customer analytics. Must reference an existing group type configured for the project. */
    account_group_type_index?: AlertsAlertCreateRequestSchema146 | null
    /** Ordered account properties shown until a user saves a personal pinned-property selection. Pass an empty list to show no properties by default. */
    default_pinned_properties?: CoreProjectSettingsUpdateRequestSchema147
}

export interface CoreProjectSettingsUpdateInputWorkflowsConfig {
    /** When enabled, workflows engagement activity (email sends, opens, clicks, bounces, spam reports, unsubscribes) is captured as standard PostHog events ($workflows_email_*) alongside the existing workflow metrics. */
    capture_workflows_engagement_events?: CoreProjectSettingsUpdateRequestSchema148
    /** Recipient-consent enforcement for open/click tracking on marketing workflow emails. 'off': no enforcement, tracking follows each email step's own setting. 'opt_out': track by default but not recipients who have opted out. 'opt_in': only track recipients who have explicitly opted in. Transactional emails are exempt from consent enforcement.
     *
     * * `off` - Off
     * * `opt_out` - Opt Out
     * * `opt_in` - Opt In */
    email_tracking_consent_mode?: CoreProjectSettingsUpdateRequestSchema149
    /** Whether new email steps and broadcasts start with UTM tags on their links. Each email can still change it. Existing emails change only through apply_utm_defaults. */
    email_utm_tags_enabled?: CoreProjectSettingsUpdateRequestSchema150
    /** Default UTM values that new email steps and broadcasts copy. An empty value keeps the built-in default for that tag. */
    email_utm_params?: CoreProjectSettingsUpdateRequestSchema151
    /** Whether tracked links in emails this project sends get a ph_workflow_run parameter with the send's run ID. When the landing page runs posthog-js, the parameter links each click to the session it starts. Links with click tracking turned off never get it. On by default. */
    email_workflow_run_link_tag_enabled?: CoreProjectSettingsUpdateRequestSchema156
    /** How many AI tasks one workflow can create in a rolling 24 hours. Null uses the default of 100; zero pauses task creation for every workflow in the project. Support raises the limit above 500. */
    workflow_task_rate_limit_per_day?: CoreProjectSettingsUpdateRequestSchema157 | null
    /** How many AI tasks all workflows in the project can create together in a rolling 24 hours. Null uses the default of 500; zero pauses task creation for the project. Support raises the limit above 2500. */
    workflow_task_team_rate_limit_per_day?: CoreProjectSettingsUpdateRequestSchema158 | null
    /** How many Replay Vision scans one workflow can request in a rolling 24 hours. Null uses the default of 100; zero pauses scans for every workflow in the project. Support raises the limit above 500. */
    replay_vision_scan_rate_limit_per_day?: CoreProjectSettingsUpdateRequestSchema159 | null
    /** How many Replay Vision scans all workflows in the project request together in a rolling 24 hours. Null uses the default of 500; zero pauses scans for the project. Support raises the limit above 2500. */
    replay_vision_scan_team_rate_limit_per_day?: CoreProjectSettingsUpdateRequestSchema160 | null
    /** ID of the verified email integration that new broadcasts and workflow email steps use as their sender. Null means no default. Set automatically when the project's first email sender is verified, and cleared when that integration is deleted. */
    default_email_integration_id?: AlertsAlertUpdateRequestSchema161 | null
    /** Most marketing messages one person can get in the window, across all workflows. Set this together with marketing_frequency_cap_window_days. Set both to null to turn the cap off. */
    marketing_frequency_cap_max_messages?: CoreProjectSettingsUpdateRequestSchema162 | null
    /** Length of the rolling frequency cap window in days. Set this together with marketing_frequency_cap_max_messages. Set both to null to turn the cap off. */
    marketing_frequency_cap_window_days?: CoreProjectSettingsUpdateRequestSchema163 | null
    /** How many hours a marketing message over the frequency cap waits for a free slot before it is skipped. Null skips it right away. */
    marketing_frequency_cap_hold_hours?: CoreProjectSettingsUpdateRequestSchema164 | null
}

export interface CoreProjectSettingsUpdateInputFeatureFlagPolicyConfig {
    /** When enabled, a new feature flag needs at least one tag, and a tagged flag cannot lose its last one. A create that declares it comes from a survey, experiment, early access feature, product tour, or web experiment is exempt, because those forms have no tag input. The caller sets that declaration, so a flag can still be created without a tag. */
    require_tags?: CoreProjectSettingsUpdateRequestSchema165
    /** Domains to block from feature flag requests (/flags and /decide), up to 100. A domain also covers its subdomains. It is compared with the Origin header, or with the Referer header when Origin is missing. Entries are stored lowercase without duplicates. A pasted URL is reduced to its domain, and an internationalized domain is stored as punycode. */
    blocked_hosts?: CoreProjectSettingsUpdateRequestSchema166
    /** IPv4 or IPv6 addresses or CIDR ranges to block from feature flag requests (/flags and /decide), up to 100. Ranges can be /8 or narrower for IPv4 and /16 or narrower for IPv6. Entries are stored in canonical form without duplicates, and an IPv4-mapped IPv6 address is stored as IPv4. */
    blocked_ips?: CoreProjectSettingsUpdateRequestSchema168
}

